ee:message.ee:set-payload:
%dw 2.0
output application/json skipNullOn= "everywhere"
import * from dw::core::Strings
var hijosWithoutDefault = (vars.hijos filter ($.idRaiz == vars.actualItem.idItem)) filter (upper($.productos.clase) != "DEFAULT")
var plansWihoutDefault = vars.responseOrHomologacion.servicio.planes filter upper($.tipoPlan) != "DEFAULT"
fun iteratesObject (initial: Object, route: Array) = if (route != []) iteratesObject(initial[route[0]], route -- [route[0]]) else initial
fun findValue (item: Object,typeParam:Number, value:String, attribute:String = "") =
    if (typeParam == 1)
        (item.productos.parametros filter ($.nombre == attribute))[0].valor
    else if (typeParam == 2)
        	iteratesObject((vars.responseById.resultados[0].direcciones filter ($.idDireccion == vars.actualItem.idDireccion))[0],value splitBy ".")
    else if (typeParam == 3) 
            iteratesObject(item,value splitBy ("."))
    else null
fun mapNumConn (arr) = arr map ((item, index) -> {
                connection_number_type_id: vars.responseOrHomologacion.servicio.connection_number_type_id,
                connection_type_id: vars.responseOrHomologacion.servicio.connection_type_id,
                numero_conexion: item.numero
           })
var fecha_inicio = (vars.actualItem.fechaInicioFacturacion splitBy ("T"))[0] 
var extraNumConection =  vars.responseOrHomologacion.servicio.defaultConnectionNumber != null and vars.responseOrHomologacion.servicio.defaultConnectionNumber.atributo != null
var addContent = (vars.actualItem.productos.parametros filter $.codigo == "ATT_PS_RangoNumeracion__c")[0].valor
var hasAddContent = !isEmpty(addContent) and (upper(addContent) contains "ADD")
fun getNumbers(value:String) =  (
    (if(value contains "DEL") 
        (substringBefore(value, ";DEL")) 
    else 
        (value)) 
    splitBy (";")) map ((item, index) -> item splitBy  "-") map ((item, index) -> if (sizeOf(item) > 1) ((0 to (item[1] - item[0])) map (i) -> item[0] + i) as Array else [item[0] as Number])
---
{
  sfilluminate: {
		operacion: vars.responseOrHomologacion.operacion,
		orden_om: vars.ordenOM,
		orden_comercial: vars.actualItem.idItem,
		servicio: {
			cuenta: (vars.responseById.resultados[0].cuentasFacturacion filter ($.idCuentaFacturacion == vars.actualItem.idCuentaFacturacion))[0].cuentaFacturacion  ,
			external_service_id: vars.actualItem.idServicio,
			fecha_inicio: fecha_inicio as Date { format: "yyyy-MM-dd" } as String { format: "dd-MM-yyyy" },
			nickname: (vars.actualItem.productos.parametros filter ( upper($.nombre) == upper(p('compRevchain.nemonico')) ))[0].valor,
			servicio: vars.responseOrHomologacion.servicio.nombre default "", 
			plan: flatten(
                [
                    (vars.responseOrHomologacion.servicio.planes filter upper($.tipoPlan) == "DEFAULT") map 
                    {
						nombre: $.nombrePlan,
						parametros: $.parametros map {
						    nombre: $.nombre,
						    valor: findValue(vars.actualItem,$.tipoParametro,$.valor,$.atributo) default ""
						 }
					},(hijosWithoutDefault map (obj,index) -> 
                                do{
                                    var matched =  (plansWihoutDefault filter (upper($.tipoPlan) == upper(obj.productos.clase)))[0]
                                    ---
                                    if(matched != null)
                                    {
                                        nombre: matched.nombrePlan,
                                        parametros: matched.parametros map {
                                                                    nombre: $.nombre,
                                                                    valor: findValue(obj,$.tipoParametro,$.valor,$.atributo) default ""
                                                                }
                                    } 
                                    else null 
                                }) if (hijosWithoutDefault != [] and plansWihoutDefault != [] ) 
			]),
			(numeros_conexion: flatten((
                   [
                       (mapNumConn(vars.actualItem.numerosConexion)) if (!isEmpty(vars.actualItem.numerosConexion))
                       ,
                       (mapNumConn(flatten(hijosWithoutDefault.numerosConexion))) if (!isEmpty(flatten(hijosWithoutDefault.numerosConexion)))
                   ] ++ if(extraNumConection) [
                   		 {
				                connection_number_type_id: vars.responseOrHomologacion.servicio.connection_number_type_id,
				                connection_type_id: vars.responseOrHomologacion.servicio.connection_type_id,
				                numero_conexion: findValue(vars.actualItem,vars.responseOrHomologacion.servicio.defaultConnectionNumber.tipoParametro,vars.responseOrHomologacion.servicio.defaultConnectionNumber.valor,vars.responseOrHomologacion.servicio.defaultConnectionNumber.atributo)
				         }
                   ] else []) ++
                   (if(hasAddContent)
						flatten(getNumbers(substringAfter(addContent, "ADD:"))) map (item2, index2) -> {
							connection_number_type_id: vars.responseOrHomologacion.servicio.connection_number_type_id,
							connection_type_id: vars.responseOrHomologacion.servicio.connection_number_type_id,
							numero_conexion: item2
						}
					else [])
               )) if (!isEmpty(vars.actualItem.numerosConexion) or !isEmpty(hijosWithoutDefault.numerosConexion) or extraNumConection or hasAddContent)

  		}
    }
}

%dw 2.0
output application/json
var orden = vars.responseById.resultados[0]
var items = (orden.items filter ($.idRaiz == vars.actualItem.idItem)) + vars.actualItem
---
{
 ordenOM: orden.ordenOM,
 accounts: {
	 idBussines: orden.cliente.idCuenta default "", 
     billingAccounts: items map (o,i) -> {
            Id: (orden.cuentasFacturacion filter ($.idCuentaFacturacion == o.idCuentaFacturacion))[0].idCuentaFacturacion default "",
            numberBillingAccount:  (orden.cuentasFacturacion filter ($.idCuentaFacturacion == o.idCuentaFacturacion))[0].cuentaFacturacion default "" ,
            ciclodeFacturacion:  (orden.cuentasFacturacion filter ($.idCuentaFacturacion == o.idCuentaFacturacion))[0].cicloFacturacion default "" ,
            billingCreationDate:  ((orden.cuentasFacturacion filter ($.idCuentaFacturacion == o.idCuentaFacturacion))[0].fechaCreacion as Date { format: "dd-MM-yyyy" } as String { format: "yyyy-MM-dd" }) default "",
            diaCorteFacturacion: (orden.cuentasFacturacion filter ($.idCuentaFacturacion == o.idCuentaFacturacion))[0].corte default "" 
     }
 },
 items: items map {
         idItem: $.idItem default "",
         idOrigen: $.idOrigen default "",
         statusProvisioning: vars.statusProvisioning,
         billingStartDate: ($.fechaInicioFacturacion splitBy "T")[0] default "",
		 billingCreationDate: ($.fechaInicioFacturacion splitBy "T")[0] default ""
     },
}

