    cuenta: (vars.responseById.resultados[0].cuentasFacturacion filter $.idCuentaFacturacion == vars.actualItem.idCuentaFacturacion)[0].cuentaFacturacion,
    id_servicio_externo: vars.actualItem.idServicio,
