    sfilluminate: {
        cobro_retiro_anticipado: {
            cuenta: vars.sub_id as Number,
            cod_fact: vars.cod_fact,
            valor: vars.amt as Number,
            descripcion: p('global-var.trans_desc') ++ vars.actualItem.idOrigen,
            fecha: now() as String { format: "dd-MM-yyyy" }
        }
    }
