%dw 2.0
output application/json
var action = if ((vars.integrationsSequence[vars.counter - 1]).integracionAProcesar == p('compRevchain.inactivateBilling')) 
	p('global-var.inactivateBilling') else 
	if ((vars.integrationsSequence[vars.counter - 1]).integracionAProcesar == p('compRevchain.suspendBilling')) 
		p('global-var.suspendBilling') else 
		p('global-var.restoreBilling')
---
{
  "wsInvokeServiceProvisioningIN": {
    "services": {
      "service_particulars": [
        {
          "subscriber_id": (vars.responseById.resultados[0].cuentasFacturacion	filter $.idCuentaFacturacion == vars.actualItem.idCuentaFacturacion)[0].cuentaFacturacion,
          "action": action,
          "service": [
            {
              "action": action,
              "finder": {
                "external_service_id": vars.actualItem.idServicio,
                "active_date": {
                  "month": now().month as String,
                  "day": now().day as String,
                  "year": now().year as String
                }
              },
              ("end_date": {
                "month": ((vars.actualItem.fechaInicioFacturacion) splitBy "+")[0].month as String,
                "day": ((vars.actualItem.fechaInicioFacturacion) splitBy "+")[0].day as String,
                "year": ((vars.actualItem.fechaInicioFacturacion) splitBy "+")[0].year as String
              }) if (action == p('global-var.inactivateBilling')),
              ("suspend_start_date": {
                "month": ((vars.actualItem.fechaInicioFacturacion) splitBy "+")[0].month as String,
                "day": ((vars.actualItem.fechaInicioFacturacion) splitBy "+")[0].day as String,
                "year": ((vars.actualItem.fechaInicioFacturacion) splitBy "+")[0].year as String
              }) if (action == p('global-var.suspendBilling')),
              ("suspend_end_date":{
                "month": ((vars.actualItem.fechaInicioFacturacion) splitBy "+")[0].month as String,
                "day": ((vars.actualItem.fechaInicioFacturacion) splitBy "+")[0].day as String,
                "year": ((vars.actualItem.fechaInicioFacturacion) splitBy "+")[0].year as String
              }) if (action == p('global-var.restoreBilling'))
            }
          ]
        }
      ]
    }
  }
}
